struct Container {
    value: String,
}

fn main() {
    let mut container = Container {
        value: String::from("hello"),
    };

    // Move the struct into a function
    let returned_value = get_value(container);

    // At this point, 'container' should be dropped because it was moved
    // If we try to use 'container' here, it would cause a compile error.
    // We assert that the returned value is correct.
    assert_eq!(returned_value, "hello");

    println!("Ownership test passed");
}

fn get_value(mut container: Container) -> String {
    // Move the String out of the struct
    let value = container.value;
    // The struct 'container' is now moved and will be dropped at the end of this function
    value
}
